import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.BJ8Z5jWT.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1794305920000}'),d={name:"getting-started.md"};function n(r,e,o,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Run <strong>Curlman</strong> on your machine.</p><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><p>Download the installer from the <a href="./../../releases">Releases</a> page, or build it yourself (see <a href="#development">Development</a>).</p><p>Curlman uses the <code>curl</code> that&#39;s already on your system: <code>%SystemRoot%\\System32\\curl.exe</code> on Windows 10 and later, or <code>curl</code> on your <code>PATH</code> on macOS and Linux. To use a different binary, set the <code>CURLMAN_CURL</code> environment variable.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>Paste a command and press <strong>Enter</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://api.example.com/users&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer TOKEN&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;:&quot;John&quot;}&#39;</span></span></code></pre></div><p>Enter works like a shell. It sends the request, unless the text before the cursor ends in a line continuation (<code>\\</code> or <code>^</code>) or an open quote. In that case it adds a new line.</p><h3 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Send (or add a new line inside a quote or after <code>\\</code>)</td></tr><tr><td><code>Ctrl/Cmd + Enter</code></td><td>Send from anywhere</td></tr><tr><td><code>Shift + Enter</code></td><td>New line</td></tr><tr><td><code>Esc</code></td><td>Cancel the running request</td></tr><tr><td><code>Ctrl + Space</code></td><td>Show suggestions</td></tr><tr><td><code>Tab</code> / <code>Enter</code> / <code>Up</code> / <code>Down</code></td><td>Accept or move through suggestions</td></tr><tr><td><code>Ctrl/Cmd + L</code></td><td>Focus and select the command</td></tr><tr><td><code>Ctrl/Cmd + Shift + F</code></td><td>Format: toggle multi-line and one-line</td></tr><tr><td><code>Ctrl/Cmd + B</code></td><td>Toggle history</td></tr><tr><td><code>Ctrl/Cmd + K</code></td><td>Search history</td></tr><tr><td><code>Ctrl/Cmd + N</code></td><td>New request</td></tr><tr><td><code>Ctrl/Cmd + 1</code> / <code>2</code> / <code>3</code></td><td>Body / Headers / Timing</td></tr><tr><td><code>Ctrl/Cmd + Shift + C</code></td><td>Copy the response</td></tr></tbody></table><h3 id="what-curlman-changes-in-your-command" tabindex="-1">What Curlman changes in your command <a class="header-anchor" href="#what-curlman-changes-in-your-command" aria-label="Permalink to &quot;What Curlman changes in your command&quot;">​</a></h3><p>Curlman captures output itself, so it removes flags that would redirect or reshape it: <code>-o</code>, <code>-O</code>, <code>-i</code>, <code>-v</code>, <code>-s</code>, <code>-S</code>, <code>-w</code>, <code>-D</code>, <code>-f</code>, <code>--trace</code> and similar. Every other flag is passed to curl unchanged.</p><h2 id="_3-development" tabindex="-1">3. Development <a class="header-anchor" href="#_3-development" aria-label="Permalink to &quot;3. Development&quot;">​</a></h2><p>Requirements: Node.js 22+, Rust, and the <a href="https://tauri.app/start/prerequisites/" target="_blank" rel="noreferrer">Tauri prerequisites</a> for your platform.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # desktop app with hot reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # the same UI in a browser at http://localhost:1420</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # release app and installer</span></span></code></pre></div><p>In browser mode the Vite dev server runs curl for the page, so requests work the same as in the desktop app. Opening <code>dist/index.html</code> on its own has no backend, and the app says so.</p><p>Release output:</p><ul><li>App: <code>src-tauri/target/release/curlman.exe</code></li><li>Installer: <code>src-tauri/target/release/bundle/nsis/Curlman_&lt;version&gt;_x64-setup.exe</code></li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>Full detail: <a href="/curlman/guide">Guide</a></li><li>Source: <a href="https://github.com/mediuswareltd/curlman" target="_blank" rel="noreferrer">github.com/mediuswareltd/curlman</a></li></ul>`,21)])])}const k=t(d,[["render",n]]);export{u as __pageData,k as default};
